    if (!smsReady) {
      console.log(`[sendDepartmentalFollowupEmail] No SMS provider configured (no AT or Termii sender ID) \u2014 falling back to email for hospital ${hospitalId}`);
    } else {
      useSms = await hasSufficientSmsBalance(hospitalId);
      if (!useSms) console.log(`[sendDepartmentalFollowupEmail] Insufficient wallet \u2014 falling back to email for hospital ${hospitalId}`);
    }
